def clean(df):
    df = df[(df['Quantity'].astype(int) == df['Quantity']) & (df['Quantity'] >= 1)]
    df = df[(df['Price'] >= 0) & (df['Price'] <= 900)]
    allowed = ['Electronics', 'Accessories', 'Furniture', 'Office Supplies']
    df['Category'] = df['Category'].str.strip()
    df = df[df['Category'].isin(allowed)]
    return df

def answer(df):
    grouped = df.groupby('Category')['Revenue'].sum().reset_index()
    return {category: total for category, total in grouped.values}
